package org.securemail.client.ecosystemauth;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class CoreNotificationArrivals600Test {
  static final CoreNotificationPreferences600.Settings PRIVATE=CoreNotificationPreferences600.Settings.defaults();
  static CoreNotificationArrivals600.Notice notice(long id,long time,boolean read,String title){return new CoreNotificationArrivals600.Notice(new UUID(0,id).toString(),read,time,title);}
  @Test void initialUnreadIsBaselineAndOnlyNewUnreadRefreshPresents(){try(var tracker=new CoreNotificationArrivals600()){var first=notice(1,10,false,"old");assertTrue(tracker.observe(List.of(first),false,PRIVATE).isEmpty());assertTrue(tracker.observe(List.of(first),false,PRIVATE).isEmpty());var fresh=notice(2,11,false,"secret title");var event=tracker.observe(List.of(first,fresh),false,PRIVATE).orElseThrow();assertEquals(1,event.count());assertEquals("Новое уведомление АЕГИС.",event.text());assertFalse(event.sound());assertTrue(event.banner());assertTrue(tracker.observe(List.of(fresh),false,PRIVATE).isEmpty());}}
  @Test void loadingHistoryAndOldUnseenBackfillNeverAlert(){try(var tracker=new CoreNotificationArrivals600()){tracker.observe(List.of(notice(1,100,false,"baseline")),false,PRIVATE);assertTrue(tracker.observe(List.of(notice(2,500,false,"history")),true,PRIVATE).isEmpty());assertTrue(tracker.observe(List.of(notice(2,500,false,"history")),false,PRIVATE).isEmpty());assertTrue(tracker.observe(List.of(notice(3,90,false,"old backfill")),false,PRIVATE).isEmpty());}}
  @Test void readItemsAndDisabledPresentationStillDeduplicate(){try(var tracker=new CoreNotificationArrivals600()){tracker.observe(List.of(),false,PRIVATE);assertTrue(tracker.observe(List.of(notice(1,10,true,"read")),false,PRIVATE).isEmpty());assertTrue(tracker.observe(List.of(notice(2,11,false,"muted")),false,new CoreNotificationPreferences600.Settings(false,false,true)).isEmpty());assertTrue(tracker.observe(List.of(notice(2,11,false,"muted")),false,PRIVATE).isEmpty());}}
  @Test void explicitDetailsArePlainBoundedAndControlCharactersAreRemoved(){try(var tracker=new CoreNotificationArrivals600()){tracker.observe(List.of(),false,PRIVATE);var event=tracker.observe(List.of(notice(1,10,false,"Текст\n\u202e"+"я".repeat(300))),false,new CoreNotificationPreferences600.Settings(true,true,false)).orElseThrow();assertTrue(event.sound());assertFalse(event.text().contains("\n"));assertFalse(event.text().contains("\u202e"));assertEquals(240,event.text().length());}}
  @Test void memoryIsBoundedAndEvictedOldHistoryCannotRealert(){try(var tracker=new CoreNotificationArrivals600()){tracker.observe(List.of(notice(1,1,false,"old")),false,PRIVATE);for(int batch=0;batch<5;batch++){List<CoreNotificationArrivals600.Notice> page=new ArrayList<>();for(int n=0;n<500;n++)page.add(notice(2+batch*500+n,2+batch*500+n,false,"new"));tracker.observe(page,false,PRIVATE);assertTrue(tracker.retainedIds()<=CoreNotificationArrivals600.MAX_SEEN);}assertTrue(tracker.observe(List.of(notice(1,1,false,"old replay")),false,PRIVATE).isEmpty());}}
  @Test void closeImmediatelySuppressesQueuedOrFuturePresentationAndClearsIds(){var tracker=new CoreNotificationArrivals600();tracker.observe(List.of(notice(1,1,false,"first")),false,PRIVATE);tracker.close();assertEquals(0,tracker.retainedIds());assertTrue(tracker.observe(List.of(notice(2,2,false,"late")),false,new CoreNotificationPreferences600.Settings(true,true,false)).isEmpty());}
  @Test void rejectsExcessivePagesAndMalformedEventIds(){try(var tracker=new CoreNotificationArrivals600()){assertThrows(IllegalArgumentException.class,()->tracker.observe(Collections.nCopies(501,notice(1,1,false,"event")),false,PRIVATE));assertThrows(IllegalArgumentException.class,()->new CoreNotificationArrivals600.Notice("not-an-event",false,1,"event"));}}
}
